function officerStarRows(D,r){const p=D.starPatterns[r[2]===3?(r[3]>=4?3:2):r[2]-1];return p.flatMap(([c,abi],i)=>abi.map((v,j)=>({c:p[i+1]?.[0]||0,v,star:i+1,stage:j})))}
function officerRangeCost(a,x,y){return a.slice(x-1,y-1).reduce((n,v)=>n+v,0)}
